  function farmstead(g, good, wind) {
    const h = AK.ground(g, { w: 13, d: 9, amp: 0.02, h: (x, z) => -0.04 * z + 0.02 * (BK.fbm(x, z, 3) - 0.5) });
    const road = []; for (let i = 0; i <= 30; i++) { const x = -6.5 + i * 0.43; road.push([x, h(x, -4) + 0.02, -4]); } g.add(GK.line(road, 0x8a6a4a, 0.16));
    const L = good ? { house: [-4.2, -2.6], office: [-2.4, -2.8], store: [0.2, -3.0], work: [2.4, -2.8], pen: [3.6, 1.6], poultry: [1.0, 1.8], pond: [-3.4, 2.8], well: [-1.4, -1.0] } : { house: [3.4, 2.4], office: [-4.4, 2.6], store: [3.6, -0.8], work: [-3.8, -2.6], pen: [-2.0, -2.8], poultry: [-4.0, 0.2], pond: [1.0, -2.6], well: [0.6, 2.6] };
    const add = (o, k, s = 1) => { const [x, z] = L[k]; AK.put(g, o, x, z, h, 0, s); return o; };
    add(AK.building("house", { w: 1.6, d: 1.1, h: 0.9, roof: "rusty_corrugated_iron" }), "house"); add(AK.building("house", { w: 1.0, d: 0.8, h: 0.7, wallCol: 0xe0e8f0 }), "office"); add(AK.building("store", { w: 1.4, d: 1.0, h: 0.8 }), "store"); add(AK.building("shed", { w: 1.2, d: 0.9, h: 0.7 }), "work"); add(AK.building("pen", { w: 1.6, d: 1.2, h: 0.6 }), "pen"); add(AK.building("poultry", { w: 1.6, d: 1.0, h: 0.6 }), "poultry");
    const w = GK.water(1.6, 1.1, 0x3a6a4a, 0.9); w.position.set(L.pond[0], h(L.pond[0], L.pond[1]) + 0.03, L.pond[1]); g.add(w); g.add(AK.cyl(0.2, 0.2, 0.3, AK.pbr("clay_block_wall"), L.well[0], h(L.well[0], L.well[1]) + 0.15, L.well[1]));
    AK.put(g, AK.animal("ndama"), L.pen[0], L.pen[1], h, 1, 0.4); if (wind != null) { const a = GK.arrow([Math.cos(wind) * -3, 2.2, Math.sin(wind) * -3], [Math.cos(wind) * -1.6, 2.2, Math.sin(wind) * -1.6], 0x9ad8ff, 0.05); g.add(a); }
    return { h, L };
  }
